船橋市のオープンデータカタログには、常住人口のほかにも国勢調査関連の統計や地区別の情報が複数公開されています。全市の数字だけでなく、関心のある地区のデータと突き合わせることで、マンション開発や再開発の影響なども推測しやすくなります。

